<script setup lang="ts">
import { useFormDrafts } from '@/composables/useFormDrafts'
import { computed,defineAsyncComponent,onMounted,reactive,ref,watch } from 'vue'
import MainLayout from '@/components/MainLayout.vue'
import request from '@/utils/request'
import {useRoute} from 'vue-router'
import { useAuthStore } from '@/stores/auth'
const StockWorkForm=defineAsyncComponent(()=>import('@/views/foundation/MesOperations.vue'))
const stockCreateOpen=ref(false),workEdit=ref<Row>(),workStatus=ref('IN_PROGRESS')
function displayWorkStatus(row:Row){return ['TERMINATED','CANCELLED','SCRAP_HOLD'].includes(row.status)?'已终止':['PRODUCTION_COMPLETED','COMPLETED'].includes(row.status)||row.receipt_no||row.shipment_no?'已完工':'生产中'}
function editWork(row:Row){error.value='';workEdit.value=row;workStatus.value=displayWorkStatus(row)==='已终止'?'TERMINATED':displayWorkStatus(row)==='已完工'?'PRODUCTION_COMPLETED':'IN_PROGRESS'}
async function saveWork(){if(!workEdit.value)return;busy.value=true;try{await request.put(`/foundation/work-orders/${workEdit.value.id}`,{status:workStatus.value});workEdit.value=undefined;await load();message.value='生产工单已保存'}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function stockCreated(id:number){stockCreateOpen.value=false;await load();const work=orders.value.find(w=>Number(w.id)===id);if(work)await showTasks(work);message.value='生产工单已创建'}
type Row=Record<string,any>
const auth=useAuthStore(),tab=ref('orders'),orders=ref<Row[]>([]),tasks=ref<Row[]>([]),inspections=ref<Row[]>([]),data=reactive<Record<string,Row[]>>({}),selected=ref<Row>()
const sources=ref<Row[]>([])
async function loadSources(){if(!template.value){sources.value=[];return}try{sources.value=await request.get<Row[]>('/fulfillment/inspection-sources',{params:{kind:template.value.kind,phase:template.value.phase}})}catch(e:any){error.value=e.message}}
function selectSource(){const src=sources.value.find(s=>Number(s.id)===Number(inspection.source_id));if(src){inspection.quantity=src.quantity;inspection.qualified_quantity=src.quantity}}
const inspectionDetail=ref<Row>(); const detailResults=computed<Row[]>(()=>{try{return JSON.parse(inspectionDetail.value?.results||'[]')}catch{return []}})
const sourceNames:Row={TASK:'工序任务',PURCHASE:'采购订单',ORDER:'销售订单'}
const error=ref(''),message=ref(''),busy=ref(false),createOpen=ref(false),inspectionOpen=ref(false)
const form=reactive<Row>({}),inspection=reactive<Row>({results:{}})
const statusNames=['待领取','已派发','生产中','待质检','已完成','已取消']
const canPlan=computed(()=>[1,2,9].includes(Number(auth.effectiveRoleId)))
const canInspect=computed(()=>[4,9].includes(Number(auth.effectiveRoleId)))
const name=(r:Row)=>[r.name||r.plan_no||r.real_name||r.product_name||r.code||'未命名',r.version,r.status].filter(Boolean).join(' · ')
async function load(){try{error.value='';orders.value=await request.get<Row[]>('/fulfillment/work-orders');inspections.value=await request.get<Row[]>('/foundation/inspections');await Promise.all(['plans','bom-versions','routes','users','schedules','qc-templates','qc-lines','qc-items'].map(async k=>{data[k]=await request.get<Row[]>(k==='users'?'/mes/assignable-people?role=3':`/foundation/${k}`)}));if(selected.value)await showTasks(selected.value)}catch(e:any){error.value=e.message}}
const detailOpen=ref(false),detailLoading=ref(false),detailError=ref('')
async function showTasks(row:Row){selected.value=row;detailOpen.value=true;detailLoading.value=true;detailError.value='';tasks.value=[];try{tasks.value=await request.get<Row[]>(`/foundation/work-orders/${row.id}/tasks`)}catch(e:any){detailError.value=e.message||'任务加载失败'}finally{detailLoading.value=false}}
const selectedPlan=computed(()=>data.plans?.find(p=>Number(p.id)===Number(form.plan_id)))
function options(k:string){let rows=data[k]||[];if(['bom-versions','routes'].includes(k))rows=rows.filter(r=>Number(r.product_id)===Number(selectedPlan.value?.product_id));return rows}
watch(()=>form.plan_id,()=>{form.bom_id=options('bom-versions')[0]?.id||'';form.route_id=options('routes')[0]?.id||'';form.schedule_id=''})
function newOrder(){Object.keys(form).forEach(k=>delete form[k]);form.owner_id=data.users?.[0]?.id||'';createOpen.value=true}
async function create(){busy.value=true;try{await request.post('/foundation/work-orders',form);completeDrafts();createOpen.value=false;message.value='已冻结BOM和路线，并按工序生成任务';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function action(task:Row,kind:'start'|'report'){
  let reportQuantity:number|undefined
  if(kind==='report'){const s=window.prompt(`任务计划量 ${task.quantity}，请输入本次报工数量`);if(s===null)return;reportQuantity=Number(s);if(!Number.isInteger(reportQuantity)||reportQuantity<=0){error.value='请输入正整数';return}}
  busy.value=true
  try{if(kind==='start')await request.put(`/production-tasks/${task.id}/start`,{});else await request.post(`/production-tasks/${task.id}/report`,{reportQuantity});message.value=kind==='start'?'任务已开工':'报工成功，工序状态已更新';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}
}
const template=computed(()=>data['qc-templates']?.find(r=>Number(r.id)===Number(inspection.template_id)))
const templateItems=computed(()=>data['qc-lines']?.filter(r=>Number(r.template_id)===Number(inspection.template_id)).map(l=>data['qc-items']?.find(i=>Number(i.id)===Number(l.item_id))).filter(Boolean) as Row[]||[])
function newInspection(task?:Row){Object.keys(inspection).forEach(k=>delete inspection[k]);Object.assign(inspection,{results:{},kind:task?'PROCESS':'INCOMING',source_type:task?'TASK':'PURCHASE',source_id:task?.id||'',quantity:task?.quantity||'',qualified_quantity:task?.quantity||'',template_id:''});if(task){inspection.template_id=data['qc-templates']?.find(r=>r.kind==='PROCESS'&&Number(r.product_id)===Number(task.product_id)&&Number(r.operation_id)===Number(task.operation_id)&&['FINAL','LAST'].includes(r.phase))?.id||''}inspectionOpen.value=true;loadSources()}
function switchTemplate(){inspection.results={};inspection.source_type=(template.value?.kind||inspection.kind)==='PROCESS'?'TASK':(template.value?.kind||inspection.kind)==='SHIPPING'?'ORDER':'PURCHASE';inspection.source_id='';loadSources()}
function ensureResult(id:any){if(!inspection.results[id])inspection.results[id]={actual:'',result:'PASS'};return inspection.results[id]}
async function submitInspection(){busy.value=true;try{await request.post('/foundation/inspections',inspection);completeDrafts();inspectionOpen.value=false;message.value='检验记录已保存，符合条件的工序已放行';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
const route=useRoute()
onMounted(async()=>{await load();if(route.query.createFromPlan&&canPlan.value){
 const planId=Number(route.query.createFromPlan)
 const existing=orders.value.find(w=>Number(w.plan_id)===planId)
 if(existing){await showTasks(existing);message.value='该计划已生成生产工单，已打开现有工单'}
 else if(data.plans?.some(p=>Number(p.id)===planId)){newOrder();form.plan_id=planId}
 else error.value='未找到该生产计划，请刷新计划列表后重试'
 }if(route.query.workOrder||route.query.planId){const wo=orders.value.find(r=>route.query.workOrder?String(r.id)===String(route.query.workOrder):String(r.plan_id)===String(route.query.planId));if(wo){await showTasks(wo);const task=tasks.value.find(r=>String(r.id)===String(route.query.taskId));if(task&&canInspect.value&&task.task_status===3)newInspection(task)}}})

const completeDrafts=useFormDrafts({createOpen:{open:createOpen,fields:{form}},inspectionOpen:{open:inspectionOpen,fields:{inspection}}})
</script>
<template><MainLayout>
  <div class="flex justify-between items-center mb-5"><h1 class="text-2xl font-bold">生产工单</h1><button class="btn-secondary" @click="load">刷新</button></div>
  <p v-if="error" role="alert" class="mb-4 text-red-600">{{error}}</p><p v-if="message" class="mb-4 text-green-700">{{message}}</p>
  <section v-if="tab==='orders'" class="bg-white border rounded-xl overflow-hidden"><div class="overflow-auto"><table class="w-full text-sm text-left"><thead class="bg-gray-50"><tr><th class="p-4">工单</th><th>产品</th><th>计划数量</th><th>末道完成</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in orders" :key="row.id" class="border-t"><td class="p-4">{{row.code}}</td><td>{{row.product_name}}</td><td>{{row.quantity}}</td><td>{{row.completed_quantity}}</td><td><span :class="displayWorkStatus(row)==='已完工'?'tag-green':displayWorkStatus(row)==='已终止'?'tag-gray':'tag-blue'">{{displayWorkStatus(row)}}</span></td><td><div class="flex gap-3 whitespace-nowrap"><button class="link-btn" @click="showTasks(row)">详情</button><button v-if="canPlan" class="link-btn" @click="editWork(row)">修改</button></div></td></tr><tr v-if="!orders.length"><td colspan="6" class="text-center p-10 text-gray-400">暂无生产工单</td></tr></tbody></table></div></section>
  <div v-if="detailOpen&&selected" class="modal-mask" @click.self="detailOpen=false"><section class="modal-card max-w-4xl" role="dialog" aria-modal="true" aria-label="生产工单详情"><div class="flex justify-between items-center mb-4"><h2>生产工单详情</h2><button class="btn-secondary" @click="detailOpen=false">关闭</button></div><div class="grid grid-cols-2 md:grid-cols-4 gap-4 mb-5 text-sm"><div><p class="text-gray-500">工单编号</p><p>{{selected.code}}</p></div><div><p class="text-gray-500">产品</p><p>{{selected.product_name}}</p></div><div><p class="text-gray-500">计划数量</p><p>{{selected.quantity}}</p></div><div><p class="text-gray-500">状态</p><p>{{displayWorkStatus(selected)}}</p></div></div><p v-if="detailLoading" role="status" class="p-4">正在加载…</p><p v-if="detailError" role="alert" class="text-red-600 p-3">{{detailError}} <button class="link-btn" @click="showTasks(selected)">重试</button></p><h2 class="p-4 border-b font-semibold">{{selected.code}} · 工序任务</h2><div class="overflow-auto"><table class="w-full text-sm text-left"><thead class="bg-gray-50"><tr><th class="p-3">任务号</th><th>工序</th><th>负责人</th><th>数量</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="task in tasks" :key="task.id" class="border-t"><td class="p-3">{{task.task_no}}</td><td>{{task.sequence_no}} {{task.operation_name}}</td><td>{{task.assigned_user_name}}</td><td>{{task.quantity}}</td><td>{{statusNames[task.task_status]}}</td><td class="space-x-3"><template v-if="Number(task.assigned_user_id)===auth.currentUser?.id"><button v-if="task.task_status===1" :disabled="busy" class="text-blue-600" @click="action(task,'start')">开工</button><button v-if="task.task_status===2" :disabled="busy" class="text-blue-600" @click="action(task,'report')">报工</button></template><button v-if="task.task_status===3&&canInspect" class="text-blue-600" @click="newInspection(task)">执行过程检验</button></td></tr></tbody></table></div></section></div>
  <section v-if="tab==='inspections'" class="bg-white border rounded-xl overflow-hidden"><div class="p-4 flex justify-between border-b"><h2 class="font-semibold">来料、过程、出货检验</h2><button v-if="canInspect" class="bg-blue-600 text-white rounded-lg px-4 py-2" @click="newInspection()">新增检验记录</button></div><div class="overflow-auto"><table class="w-full text-sm text-left"><thead class="bg-gray-50"><tr><th class="p-3">检验单号</th><th>类型</th><th>来源</th><th>检验/合格数</th><th>结果</th></tr></thead><tbody><tr v-for="r in inspections" :key="r.id" class="border-t"><td class="p-3">{{r.code}}</td><td>{{({INCOMING:'来料',PROCESS:'过程',SHIPPING:'出货'} as Row)[r.kind]}}</td><td>{{sourceNames[r.source_type]}} #{{r.source_id}}</td><td>{{r.quantity}} / {{r.qualified_quantity}}</td><td :class="r.status==='RELEASED'?'text-green-700':'text-red-600'">{{r.status==='RELEASED'?'检验放行':'不合格，阻止放行'}}<button class="block text-blue-600 mt-1" @click="inspectionDetail=r">检测明细</button></td></tr><tr v-if="!inspections.length"><td colspan="5" class="p-10 text-center text-gray-400">暂无检验记录。</td></tr></tbody></table></div></section>
  <div v-if="createOpen" class="modal-mask fixed inset-0 bg-black/40 z-[80] flex justify-center items-center p-6" data-business-form><form class="modal-card bg-white rounded-xl p-6 w-full max-w-lg" @submit.prevent="create"><p class="text-xs text-gray-500 mb-3" role="note">退出填写会保留草稿；保存成功后自动关闭。</p><h2 class="text-xl font-bold mb-4">创建制造工单</h2><p v-if="error" class="text-red-600 mb-3">{{error}}</p><div v-for="f in [{key:'plan_id',label:'生产计划',lookup:'plans'},{key:'bom_id',label:'BOM版本',lookup:'bom-versions'},{key:'route_id',label:'工艺路线',lookup:'routes'},{key:'owner_id',label:'任务负责人',lookup:'users'},{key:'schedule_id',label:'关联排班（选填）',lookup:'schedules'}]" :key="f.key" class="mb-4"><label class="block mb-1 text-sm" :for="f.key">{{f.label}}</label><select :id="f.key" v-model="form[f.key]" :required="f.key!=='schedule_id'" class="border rounded-lg p-2 w-full"><option value="">请选择</option><option v-for="r in options(f.lookup)" :key="r.id" :value="r.id">{{name(r)}}</option></select><p v-if="!options(f.lookup).length" class="text-amber-700 text-sm">暂无可选{{f.label}}，请先完善对应产品资料或生产计划。</p></div><div class="flex justify-end gap-3"><button type="button" @click="createOpen=false">取消</button><button :disabled="busy" class="bg-blue-600 text-white rounded-lg px-4 py-2">冻结并下发</button></div></form></div>
  <div v-if="inspectionOpen" class="modal-mask fixed inset-0 bg-black/40 z-[80] flex justify-center items-center p-6" data-business-form><form class="modal-card bg-white rounded-xl p-6 w-full max-w-2xl max-h-[90vh] overflow-auto" @submit.prevent="submitInspection"><p class="text-xs text-gray-500 mb-3" role="note">退出填写会保留草稿；保存成功后自动关闭。</p><h2 class="text-xl font-bold mb-4">执行质量检验</h2><p v-if="error" class="text-red-600 mb-3">{{error}}</p><label class="block mb-1">检验类型</label><select v-model="inspection.kind" class="border rounded-lg p-2 w-full mb-4" @change="inspection.template_id='';switchTemplate()"><option value="INCOMING">来料检验（采购来源）</option><option value="PROCESS">过程检验（工序来源）</option><option value="SHIPPING">出货检验（订单来源）</option></select><label class="block mb-1">检测模板</label><select v-model="inspection.template_id" required class="border rounded-lg p-2 w-full mb-4" @change="switchTemplate"><option value="">请选择</option><option v-for="r in (data['qc-templates']||[]).filter(t=>t.kind===inspection.kind)" :key="r.id" :value="r.id">{{r.name}} · {{r.version}}</option></select><div class="grid grid-cols-3 gap-3 mb-4"><label class="text-sm">{{sourceNames[inspection.source_type]}}<select v-model="inspection.source_id" required class="border rounded p-2 w-full" @change="selectSource"><option value="">请选择有效来源</option><option v-for="s in sources.filter(s=>(!s.product_id||Number(s.product_id)===Number(template?.product_id))&&(!s.operation_id||Number(s.operation_id)===Number(template?.operation_id)))" :key="s.id" :value="s.id">{{s.name}}</option></select></label><p v-if="!sources.length" class="text-amber-700 text-sm col-span-3">没有可检验来源：请先选择检测模板，并检查采购审批、工序报工或成品入库是否完成。</p><label class="text-sm">检验数量<input v-model="inspection.quantity" type="number" min="1" required class="border rounded p-2 w-full" /></label><label class="text-sm">合格数量<input v-model="inspection.qualified_quantity" type="number" min="0" required class="border rounded p-2 w-full" /></label></div><div v-for="item in templateItems" :key="item.id" class="border rounded-lg p-3 mb-3"><p class="font-medium">{{item.name}}</p><p class="text-gray-500 text-sm mb-2">{{item.standard}}</p><div class="flex gap-2"><input v-model="ensureResult(item.id).actual" required placeholder="输入实际检测值或现象" class="border rounded p-2 flex-1" /><select v-model="ensureResult(item.id).result" class="border rounded p-2"><option value="PASS">合格</option><option value="FAIL">不合格</option></select></div></div><div class="flex justify-end gap-3 mt-4"><button type="button" @click="inspectionOpen=false">取消</button><button :disabled="busy||!templateItems.length" class="bg-blue-600 text-white rounded-lg px-4 py-2">提交检验结果</button></div></form></div>
<div v-if="inspectionDetail" class="modal-mask fixed inset-0 z-[90] bg-black/40 flex justify-center items-center p-6" data-business-form @click.self="inspectionDetail=undefined"><section class="modal-card bg-white rounded-xl p-6 max-w-2xl w-full max-h-[85vh] overflow-auto"><div class="flex justify-between mb-4"><h2 class="font-bold text-xl">检测明细</h2><button class="border rounded px-3 py-1" @click="inspectionDetail=undefined">关闭</button></div><p class="text-gray-500 text-sm mb-4">{{inspectionDetail.code}} · 以下标准和实测结果保存于检验执行时。</p><div v-for="(result,i) in detailResults" :key="i" class="border rounded-lg p-4 mb-3"><p class="font-semibold">{{result.item.name}}</p><p class="text-sm text-gray-500 my-2">标准：{{result.item.standard}}</p><p>实测：{{result.actual}}</p><p class="mt-2" :class="result.result==='PASS'?'text-green-700':'text-red-600'">{{result.result==='PASS'?'合格':'不合格'}}</p></div></section></div><div v-if="workEdit" class="modal-mask"><form class="modal-card max-w-lg space-y-4" @submit.prevent="saveWork"><h2>修改生产工单</h2><p>{{workEdit.code}}</p><label class="block">状态<select v-model="workStatus" class="input"><option value="IN_PROGRESS">生产中</option><option value="PRODUCTION_COMPLETED">已完工</option><option value="TERMINATED">已终止</option></select></label><p v-if="error" class="text-red-600">{{error}}</p><div class="flex justify-end gap-3"><button type="button" class="btn-secondary" @click="workEdit=undefined">取消</button><button class="btn-primary" :disabled="busy">保存</button></div></form></div><StockWorkForm v-if="stockCreateOpen" embedded initial-tab="work-orders" form-only @close="stockCreateOpen=false" @created="stockCreated" /></MainLayout></template>
